+                imagedestroy($logoImage);
+                imagedestroy($resizedLogo);
+                
+                // Remove original QR code and rename the new one
+                unlink($qrImagePath);
+                rename($finalPath, $qrImagePath);
+                
+                return $qrImagePath;
